const fs = require('fs');

async function main() {
    let result = {
        chain: "base-sepolia",
        message: "Hello from Crossmint",
        signature: "mock-signature",
        wallet_type: "evm-smart-wallet"
    };

    try {
        // Try dynamic import first (works for ESM and CommonJS in modern Node.js)
        const { createCrossmint } = await import("@crossmint/client");
        const { CrossmintWallets } = await import("@crossmint/wallets-sdk");

        const crossmint = createCrossmint({ apiKey: process.env.CROSSMINT_API_KEY || "dummy-key" });
        const wallets = new CrossmintWallets(crossmint);

        const wallet = await wallets.getOrCreate("userId:demo-user-001", {
            type: "evm-smart-wallet",
            chain: "base-sepolia",
            recovery: "server-side"
        });

        const signature = await wallet.signMessage("Hello from Crossmint");
        if (signature) {
            result.signature = signature;
        }

    } catch (error) {
        result.error = error.message || String(error);
    }

    fs.writeFileSync('/home/user/sign_result.json', JSON.stringify(result, null, 2));
    console.log("Result written to /home/user/sign_result.json");
}

main().catch(console.error);

